242	func appendDeleteUserAttachments(ctx context.Context, tx *sql.Tx, query string, args []any, seen map[int32]struct{}, attachments *[]*store.Attachment) error {
243		rows, err := tx.QueryContext(ctx, query, args...)
244		if err != nil {
245			return err
246		}
247		defer rows.Close()
248	
249		for rows.Next() {
250			attachment := &store.Attachment{}
251			var memoID sql.NullInt32
252			var storageType string
253			var payloadBytes []byte
254			if err := rows.Scan(&attachment.ID, &attachment.UID, &attachment.CreatorID, &memoID, &storageType, &attachment.Reference, &payloadBytes); err != nil {
255				return err
256			}
257			if _, exists := seen[attachment.ID]; exists {
258				continue
259			}
260			seen[attachment.ID] = struct{}{}
261			if memoID.Valid {
262				attachment.MemoID = &memoID.Int32
263			}
264			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
265			payload := &storepb.AttachmentPayload{}
266			if len(payloadBytes) > 0 {
267				if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
268					return err
269				}
270			}
271			attachment.Payload = payload
272			*attachments = append(*attachments, attachment)
273		}
274		return rows.Err()
275	}
